// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a simple ERC20-like token that tracks balances
        Token token = new Token();
        // Give the contract some tokens to transfer
        token.mint(address(c), 100);
        // Prepare recipients
        address[] memory tos = new address[](2);
        tos[0] = address(0x123);
        tos[1] = address(0x456);
        // Call transfer, which will call token.transferFrom from address(c) to each recipient
        // The reference calls it for both recipients; buggy version only for first
        bool ok;
        try c.transfer(address(c), address(token), tos, 1) {
            ok = true;
        } catch {
            ok = false;
        }
        // The reference would have called transferFrom twice, so token balance of first recipient is 1
        // The buggy version calls it only once (first recipient gets 1, second gets 0)
        assertTrue(token.balances(address(0x123)) == 1);
    }
}

contract Token {
    mapping(address => uint) public balances;
    function mint(address to, uint amount) public {
        balances[to] += amount;
    }
    function transferFrom(address from, address to, uint amount) public returns (bool) {
        require(balances[from] >= amount);
        balances[from] -= amount;
        balances[to] += amount;
        return true;
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    // a simple helper to count calls
    address helper;

    constructor() {
        helper = address(new Helper());
    }

    function setUp() public {
        c = new C();
    }

    function testRegression_property() public {
        address[] memory tos = new address[](2);
        tos[0] = address(0x1);
        tos[1] = address(0x2);
        c.transfer(address(this), helper, tos, 1);
        // reference call: both addresses called, helper's count = 2
        // buggy call: only first address called, count = 1
        assertTrue(Helper(helper).count() == 2);
    }
}

contract Helper {
    uint256 public count;

    function transferFrom(address, address, uint256) external returns (bool) {
        count++;
        return true;
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a simple ERC20 mock that tracks balances
        ERC20Mock token = new ERC20Mock();
        address tokenAddr = address(token);
        token.mint(address(this), 100);
        token.approve(address(c), 100);

        address[] memory tos = new address[](2);
        tos[0] = address(0x1);
        tos[1] = address(0x2);

        // Call transfer on the buggy/reference contract
        c.transfer(address(this), tokenAddr, tos, 1);

        // Assert that the second address received the token (only in reference)
        // Buggy version skips the last address, so its balance remains 0
        assertTrue(token.balanceOf(tos[1]) == 1);
    }
}

contract ERC20Mock {
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    function mint(address to, uint256 amount) external {
        balanceOf[to] += amount;
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        require(allowance[from][msg.sender] >= amount);
        allowance[from][msg.sender] -= amount;
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        return true;
    }
}
